import fs from "node:fs";
import process from "node:process";

/**
 * Shared state-park authority guardrails. The explicit missing-facilities inventory
 * is a review backlog, not evidence that an amenity is absent. No autogenerated
 * text may satisfy a park-specific facts requirement.
 */
const read = (path) => fs.readFileSync(path, "utf8");
const authority = read("src/data/state-park-authority.ts");
const headquarters = read("src/data/state-park-verified-locations.ts");
const newOpenings = read("src/data/newly-opened-state-parks-2026.ts");
const historicCanonical = read("src/data/canonical-historic-state-parks.ts");
const hillCountry = read("src/data/hill-country-state-natural-area-authority.ts");
const recovery = read("src/data/state-park-authority-recovery.ts");
const planner = read("src/components/editorial/DestinationVisitPlanner.tsx");
const essentials = read("src/components/editorial/StateParkVisitorEssentials.tsx");
const runtime = read("src/data/destination-query-runtime.ts");
const preserved = read("src/data/destination-preserved-catalog.ts");
const curation = read("src/data/destination-curation-all.ts");
const availability = read("src/data/destination-availability.ts");
const parkHeroes = read("src/data/state-park-hero-map.ts");
const legacyExplore = read("src/data/fixtures/legacy-explore.ts");
const legacyLakes = read("src/data/fixtures/legacy-lakes.ts");
const failures = [];

function assertContains(text, substring, what) {
  if (!text.includes(substring)) failures.push(what);
}
for (const [content, needle, description] of [
  [authority, "isTexasStateParkDestination", "State-park classification must distinguish park properties from unrelated RV businesses"],
  [authority, "VERIFIED_PARK_FACILITIES", "Facility notes must cite park-specific TPWD sources"],
  [planner, "<StateParkVisitorEssentials destination={destination} />", "Destination template must display park-specific essentials"],
  [essentials, "Park-specific facility verification pending", "Unknown facilities must not be represented as present"],
  [essentials, "Official park, parking and trails maps", "Every TPWD park must expose a park-map discovery route"],
  [essentials, "Fees, campsites and facility types", "Every TPWD park must expose official fees/facilities source"],
  [runtime, 'params.category === "state-parks"', "Explore State Parks must include parks from other topical categories"],
  [runtime, ".filter(isTexasStateParkDestination)", "The Explore park directory must apply official ownership and name classification"],
  [preserved, "stateParkAuthorityRecoveryDestinations,", "Missing parks must remain resolvable during remote data outages"],
  [curation, "applyStateParkAuthorityRecovery,", "Reviewed canonical facts must override thin imported park records"],
  [availability, "UNAVAILABLE_DESTINATION_SLUGS", "Closed parks must not be surfaced as visitable destinations"],
]) assertContains(content, needle, description);

assertContains(newOpenings, 'slug: "palo-pinto-mountains-state-park"', "March 2026 Palo Pinto Mountains open park must have a canonical authority guide");
assertContains(newOpenings, 'CC BY 3.0', "New state park hero must have source-confirmed license");
assertContains(preserved, "newlyOpenedStateParks2026,", "2026 opening must resolve even when remote Explore is unavailable");
assertContains(curation, "applyNewlyOpenedStateParkAuthority,", "Do not overwrite 2026 research with older short imported copy");
for (const slug of ["goliad-state-park-and-historic-site", "hueco-tanks-state-park-and-historic-site", "lyndon-b-johnson-state-park-and-historic-site"]) {
  assertContains(historicCanonical, `to: "${slug}"`, `Missing verified historic state park primary canonical path ${slug}`);
}
assertContains(preserved, "canonicalHistoricStateParkDestinations,", "Canonical historic parks missing from resilient Explore catalog");
assertContains(curation, "applyCanonicalHistoricStatePark,", "Canonical historic research must override legacy short curation");
assertContains(hillCountry, 'slug: "hill-country-state-natural-area"', "Missing Hill Country Natural Area visitor and campground authority page");
assertContains(hillCountry, 'CC BY 4.0', "Hill Country exact-place hero license missing");
assertContains(preserved, "[hillCountryStateNaturalAreaAuthority],", "Hill Country fallback must remain available when remote is down");
assertContains(curation, "applyHillCountryStateNaturalAreaAuthority,", "TPWD campsite facts must override generic Hill Country copy");
const required = [
  "fort-richardson-state-park-state-historic-site",
  "seminole-canyon-state-park-and-historic-site",
  "lake-arrowhead-state-park",
];
const verifiedParkSlugs = ["palo-duro-canyon-state-park","caprock-canyons-state-park","big-bend-ranch-state-park","mustang-island-state-park","goose-island-state-park","sea-rim-state-park","fort-boggy-state-park","copper-breaks-state-park","san-angelo-state-park","abilene-state-park","daingerfield-state-park","mission-tejas-state-park"];
for (const slug of verifiedParkSlugs) {
  assertContains(headquarters, `"${slug}": {`, `Missing individually verified TPWD headquarters: ${slug}`);
  assertContains(authority, `"${slug}": {`, `Missing verified TPWD park facilities: ${slug}`);
}
assertContains(curation, "applyVerifiedStateParkHeadquarters,", "Independently researched park entrance locations must be applied to published destination pages");
for (const slug of required) {
  assertContains(recovery, `slug: "${slug}"`, `Canonical recovery guide missing: ${slug}`);
  assertContains(authority, `"${slug}": {`, `Missing documented park-specific facilities verification: ${slug}`);
}
for (const marker of ["sourceCheckedAt: \"2026-10-12\"", "CC BY", "officialUrl: \"https://tpwd.texas.gov/state-parks/", "body: ["]) {
  assertContains(recovery, marker, `Recovery guides lack editorial provenance field: ${marker}`);
}

const candidate = new Set();
for (const src of [legacyExplore, legacyLakes]) {
  for (const line of src.split("\n")) {
    if (!line.includes("https://tpwd.texas.gov/state-parks/")) continue;
    const slug = line.split("|")[0];
    if (/^[a-z0-9-]+$/.test(slug) && /state-park|state-natural-area/.test(slug)) candidate.add(slug);
  }
}
for (const match of parkHeroes.matchAll(/"([a-z0-9-]+)"\s*:\s*\{\s*src:/g)) {
  if (/state-park|state-natural-area/.test(match[1])) candidate.add(match[1]);
}
const knownAlias = new Set();
for (const set of ["NON_PRIMARY_TRIP_PLANNER_SLUGS", "UNAVAILABLE_DESTINATION_SLUGS"]) {
  const start = availability.indexOf(`const ${set}`);
  const end = availability.indexOf("]);", start);
  if (start < 0 || end < 0) failures.push(`Cannot identify availability guard: ${set}`);
  else for (const match of availability.slice(start, end).matchAll(/"([^"]+)"/g)) knownAlias.add(match[1]);
}
const unresolvedCandidates = [...candidate].filter((slug) => !knownAlias.has(slug) && !required.includes(slug));
process.stdout.write(`State-park authority: 3 emergency canonical records guarded; ${unresolvedCandidates.length} additional park-related fixture/image slugs need individual facilities, photography, links and publication review.\n`);
if (failures.length) {
  for (const problem of failures) process.stderr.write(`FAIL ${problem}\n`);
  process.exitCode = 1;
} else {
  process.stdout.write("PASS State park canonical recovery, Explore inclusion, source transparency and visitor map/facility contracts.\n");
}
